export function restoreMobs(section: DimensionSection): SavedMob[] {
  if (!Array.isArray(section.mobs)) return [];
  const out: SavedMob[] = [];
  for (const entry of section.mobs) {
    if (!entry || typeof entry.kind !== "string" || !MOB_TEMPLATES[entry.kind]) continue;
    if (!Number.isFinite(entry.x) || !Number.isFinite(entry.y) || !Number.isFinite(entry.z)) continue;
    if (!Number.isFinite(entry.hp) || entry.hp <= 0) continue;
    if (typeof entry.faction !== "string" || !Object.hasOwn(VALID_MOB_FACTIONS, entry.faction)) continue;
    // Only the two persistent shapes are accepted (mirrors isPersistentMob), so a
    // stale/edited save can't resurrect e.g. a "pet zombie": an owned ally pet, or
    // an owner-less villager resident. Anything else is dropped.
    const isPet = typeof entry.owner === "string" && entry.owner.length > 0 && entry.faction === "ally";
    const isResident = entry.owner == null && entry.faction === "villager";
    if (!isPet && !isResident) continue;
    const saved: SavedMob = { kind: entry.kind, x: entry.x, y: entry.y, z: entry.z, hp: entry.hp, faction: entry.faction };
    if (typeof entry.owner === "string" && entry.owner.length > 0) saved.owner = entry.owner;
    if (entry.sitting === true) saved.sitting = true;
    if (Number.isFinite(entry.ageTimer) && (entry.ageTimer ?? 0) > 0) saved.ageTimer = entry.ageTimer;
    if (isProfession(entry.profession)) saved.profession = entry.profession;
    out.push(saved);
  }
  return out;
}

/**
 * Reads chest containers from a save into validated, CHEST_SLOTS-length slot
 * arrays keyed by voxel index. Per-slot validation only — the engine still
 * confirms each index actually holds a Chest block before using it.
 */
export function readContainers(section: DimensionSection): Array<{ index: number; slots: InventorySlot[] }> {
  if (!Array.isArray(section.blockEntities)) return [];
  const out: Array<{ index: number; slots: InventorySlot[] }> = [];
  for (const entry of section.blockEntities) {
    if (!entry || !Number.isFinite(entry.index) || !Array.isArray(entry.slots)) continue;
    const slots = Array.from({ length: CHEST_SLOTS }, (_, i) => restoreSlot(entry.slots[i]));
    out.push({ index: entry.index, slots });
  }
  return out;
}

